let tuitionSearchQuery='';
function tuitionSearchNormalize(value){return String(value||'').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[\s\u200c\u200e\u200f]/g,'').toLowerCase()}
function filterTuitionLearners(value){tuitionSearchQuery=value;const q=tuitionSearchNormalize(value);let count=0;document.querySelectorAll('.learner-tuition-accordion').forEach(el=>{const show=!q||el.dataset.search.includes(q);el.hidden=!show;if(show)count++});const status=document.getElementById('tuition-search-count');if(status)status.textContent=count.toLocaleString('fa-IR')+' کلاس از '+document.querySelectorAll('.learner-tuition-accordion').length.toLocaleString('fa-IR')+' کلاس';const empty=document.getElementById('tuition-search-empty');if(empty)empty.hidden=count!==0}
/* Per-course tuition controls and named navigation. */
const reviewBeforeTuitionPolish=reviewEnrollment;
reviewEnrollment=function(id){reviewBeforeTuitionPolish(id);if(!admin)return;const fields=$('fields');
 const enhance=box=>{if(box.dataset.tuitionBound)return;box.dataset.tuitionBound='true';const index=[...fields.querySelectorAll('.review-extra-course')].indexOf(box),prefix='course_'+index+'_',section=document.createElement('fieldset');section.className='tuition-setup';section.innerHTML='<legend>شهریهٔ مستقل این کلاس</legend><p class="sub">وضعیت پرداخت این چهار جلسه فقط برای همین استاد ثبت می‌شود.</p><div class="tuition-controls"></div>';const grid=section.querySelector('div');
 for(const key of ['month_key','discount_percent','p1','p2','p3','p4','note']){const source=$('form').elements[key],label=source.closest('label').cloneNode(true),input=label.querySelector('select,input,textarea');input.name=prefix+key;input.dataset.tuitionKey=key;input.removeAttribute('id');label.querySelectorAll('small').forEach(x=>x.remove());if(key==='month_key'||key==='note')label.classList.add('full-field');if(/^p/.test(key))input.value='false';if(key==='note')input.value='';grid.append(label)}box.append(section);const preview=document.createElement('p');preview.className='policy';preview.setAttribute('aria-live','polite');section.append(preview);const discount=box.querySelector('[data-tuition-key="discount_percent"]');discount.value='0';const updatePrice=()=>{const percent=Number(digits(discount.value));discount.setCustomValidity(Number.isFinite(percent)&&percent>=0&&percent<=100?'':'درصد تخفیف باید بین صفر و صد باشد');preview.textContent='شهریهٔ نهایی ۴ جلسه: '+money(tuitionUnit({discount_percent:percent})*4)+' تومان · '+money(percent)+'٪ تخفیف';};discount.addEventListener('input',updatePrice);updatePrice();
 const update=()=>{const month=box.querySelector('[data-tuition-key="month_key"]').value,day=box.querySelector('[data-course-key="weekday"]').value,dates=tuitionDates(month,day);for(let i=1;i<=4;i++){const label=box.querySelector('[data-tuition-key="p'+i+'"]').closest('label');let small=label.querySelector('small');if(!small){small=document.createElement('small');label.append(small)}small.textContent=dates[i-1]?AcademyDates.show(dates[i-1]):''}};box.addEventListener('change',update);update();};
 fields.querySelectorAll('.review-extra-course').forEach(enhance);const observer=new MutationObserver(()=>fields.querySelectorAll('.review-extra-course').forEach(enhance));observer.observe(fields,{childList:true});modal.addEventListener('close',()=>observer.disconnect(),{once:true});
};
const apiBeforeIndependentReview=api;
api=async function(path,method='GET',body){if(path==='/rest/v1/rpc/approve_enrollment_with_tuition'&&method==='POST'){
 const extras=[...$('fields').querySelectorAll('.review-extra-course')].map(box=>{const data=Object.fromEntries([...box.querySelectorAll('[data-course-key]')].map(el=>[el.dataset.courseKey,el.value]));for(const key of ['month_key','discount_percent','note'])data[key]=box.querySelector('[data-tuition-key="'+key+'"]').value;data.paid=[1,2,3,4].map(i=>box.querySelector('[data-tuition-key="p'+i+'"]').value==='true');return data});
 const d=body.data;return enrollmentApiOneCourse('/rest/v1/rpc/approve_multi_enrollment',method,{data:{...d,courses:[{teacher_id:d.teacher_id,subject:d.subject,weekday:d.weekday,class_time:d.class_time,month_key:d.month_key,paid:d.paid,discount_percent:d.discount_percent,note:d.note},...extras]}});
 }return apiBeforeIndependentReview(path,method,body)};
function jumpToLearnerTuition(id){tuitionSearchQuery='';go('monthly');const el=document.getElementById('tuition-learner-'+id);if(el){el.open=true;el.querySelector('summary')?.focus({preventScroll:true})}}
const monthlyBeforeNamedNavigation=views.monthly;
views.monthly=function(){const html=monthlyBeforeNamedNavigation();if(!office)return html;const holder=document.createElement('div');holder.innerHTML=html;const list=db.students.filter(s=>!s.archived_at&&monthRows.some(t=>t.student_id===s.id));const cards=[...holder.querySelectorAll('.card')].filter(c=>c.querySelector('.tuition-months'));
 cards.forEach((card,i)=>{if(!list[i])return;card.id='tuition-learner-'+list[i].id;card.tabIndex=-1;card.classList.add('tuition-learner-section');const heading=card.querySelector('h3');if(heading)heading.textContent=full(list[i])+' · '+classLabel(list[i]);});
 for(const s of db.students.filter(s=>!s.archived_at&&!list.some(c=>c.id===s.id))){const card=document.createElement('section');card.className='card tuition-learner-section';card.id='tuition-learner-'+s.id;card.tabIndex=-1;card.innerHTML='<h3>'+esc(full(s))+' · '+esc(classLabel(s))+'</h3><p>شهریهٔ این کلاس هنوز تنظیم نشده است.</p>'+(admin?'<button onclick="editMonth(\''+s.id+'\')">تنظیم شهریهٔ این کلاس</button>':'');holder.append(card);list.push(s)}const nav=document.createElement('section');nav.className='learner-jump-list learner-accordion-list';nav.setAttribute('aria-label','شهریهٔ هنرجویان');nav.innerHTML='<strong>هنرجو را انتخاب کنید</strong><div class="tuition-search-bar"><label for="tuition-learner-search">جست‌وجوی سریع هنرجو</label><div><input id="tuition-learner-search" type="search" autocomplete="off" placeholder="نام هنرجو، کد ملی، استاد یا رشته…" value="'+esc(tuitionSearchQuery)+'" oninput="filterTuitionLearners(this.value)"><button type="button" onclick="document.getElementById(\'tuition-learner-search\').value=\'\';filterTuitionLearners(\'\');document.getElementById(\'tuition-learner-search\').focus()">پاک کردن</button></div><small id="tuition-search-count" role="status" aria-live="polite"></small></div>';for(const s of list){const card=holder.querySelector('[id="tuition-learner-'+s.id+'"]');if(!card)continue;card.removeAttribute('id');card.removeAttribute('tabindex');const details=document.createElement('details');details.className='learner-tuition-accordion';details.id='tuition-learner-'+s.id;details.dataset.search=tuitionSearchNormalize(full(s)+' '+s.national_id+' '+teacher(s.teacher_id)+' '+s.subject);details.hidden=!!tuitionSearchQuery&&!details.dataset.search.includes(tuitionSearchNormalize(tuitionSearchQuery));const summary=document.createElement('summary');summary.innerHTML='<span>'+esc(full(s))+'</span><small>'+esc(s.subject)+' · '+esc(teacher(s.teacher_id))+'</small><b aria-hidden="true">⌄</b>';details.append(summary,card);nav.append(details)}const matches=nav.querySelectorAll('details:not([hidden])').length;nav.querySelector('#tuition-search-count').textContent=matches.toLocaleString('fa-IR')+' کلاس از '+list.length.toLocaleString('fa-IR')+' کلاس';const empty=document.createElement('p');empty.id='tuition-search-empty';empty.className='empty';empty.textContent='نتیجه‌ای پیدا نشد؛ نام یا کد ملی دیگری را جست‌وجو کنید.';empty.hidden=matches!==0;nav.append(empty);if(list.length){const title=holder.querySelector('.title');if(title)title.after(nav);else holder.prepend(nav)}return holder.innerHTML};
const studentTableBeforeNamedLinks=studentTable;
studentTable=function(list){const holder=document.createElement('div');holder.innerHTML=studentTableBeforeNamedLinks(list);learnerGroups(list).forEach((courses,i)=>{const row=holder.querySelectorAll('tbody tr')[i],name=row?.querySelector('td b');if(!name)return;const button=document.createElement('button');button.className='learner-name-link';button.type='button';button.textContent=full(courses[0]);button.setAttribute('onclick',"jumpToLearnerTuition('"+courses[0].id+"')");name.replaceWith(button)});return holder.innerHTML};
render();
